template <typename T>
struct Processor {
    static const char* type() { return "Generic"; }
};

// Full Specialization for int
template <>
struct Processor<int> {
    static const char* type() { return "Integer"; }
};

// Partial Specialization for pointers
template <typename T>
struct Processor<T*> {
    static const char* type() { return "Pointer"; }
};

// SFINAE via std::enable_if for overload resolution
template <typename T>
typename std::enable_if<std::is_floating_point_v<T>, T>::type
value_op(T val) { return val / 2.0; }

template <typename T>
typename std::enable_if<!std::is_floating_point_v<T>, T>::type
value_op(T val) { return val; }
